);

export const deleteRisk = createAsyncThunk(
  'projects/deleteRisk',
  async (riskId: number) => {
    await api.deleteRisk(riskId);
    return riskId;
  }
);

// --- Slice Definition ---
const projectSlice = createSlice({
  name: 'projects',
  initialState,
  reducers: {
    setCurrentProject(state, action: PayloadAction<number | null>) {
        if (action.payload === null) {
            state.currentProject = null;
        } else {
            state.currentProject = state.projects.find(p => p.id === action.payload) || null;
        }
    },
    // The following reducers will be used by WbsTable, but will dispatch async thunks later
    addTask(state, action: PayloadAction<Partial<Task>>) {
        // This will be refactored to dispatch an async thunk
        const newTask: Task = {
          id: -1, // Temporary ID, will be replaced by backend ID
          text: action.payload.text || 'New Task',
          start_date: action.payload.start_date || new Date().toISOString().slice(0,10),
          duration: action.payload.duration ?? 1,
          progress: action.payload.progress ?? 0,
          parent: action.payload.parent ?? null,
          predecessors: [], // Predecessors not yet handled in backend Task model
          cost: action.payload.cost ?? 0,
          resource_id: action.payload.resource_id,
          project_id: state.currentProject?.id ?? -1, // Temporary project_id
        };
        state.tasks.push(newTask);
    },
    updateTaskParent(state, action: PayloadAction<{ id: number; parent: number | null }>) {
        const task = state.tasks.find(t => t.id === action.payload.id);
        if (task) {
            task.parent = action.payload.parent;
        }
    },
    updateTaskField(state, action: PayloadAction<{ id: number; field: keyof Task; value: unknown }>) {
        const task = state.tasks.find(t => t.id === action.payload.id);
        if (task) {
          const { field, value } = action.payload;
          // Narrowing based on field
          switch (field) {
            case 'text':
            case 'start_date':
              task[field] = (value as string) ?? '';
              break;
            case 'parent':
            case 'duration':
            case 'progress':
            case 'cost':
              task[field] = Number(value);
              break;
            case 'predecessors':
              // Predecessors not yet handled in backend Task model
              break;
            case 'resource_id':
                task[field] = (value as number);
                break;
            default:
              break;
          }
        }
    },
  },
  extraReducers: (builder) => {
    builder
      // fetchProjects
      .addCase(fetchProjects.pending, (state) => {
        state.status = 'loading';
      })
      .addCase(fetchProjects.fulfilled, (state, action) => {
        state.status = 'succeeded';
        state.projects = action.payload;
      })
      .addCase(fetchProjects.rejected, (state, action) => {
        state.status = 'failed';
        state.error = action.error.message || 'Failed to fetch projects';
      })
      // fetchProjectDetails
      .addCase(fetchProjectDetails.pending, (state) => {
        state.status = 'loading';
      })
      .addCase(fetchProjectDetails.fulfilled, (state, action) => {
        state.status = 'succeeded';
        state.currentProject = action.payload.project;
        state.tasks = action.payload.tasks;
        state.resources = action.payload.resources;
        state.risks = action.payload.risks;
      })
      .addCase(fetchProjectDetails.rejected, (state, action) => {
        state.status = 'failed';
        state.error = action.error.message || 'Failed to fetch project details';
      })
      // createProject
      .addCase(createProject.fulfilled, (state, action) => {
        state.projects.push(action.payload);
        state.status = 'succeeded';
      })
      // createTask
      .addCase(createTask.fulfilled, (state, action) => {
        state.tasks.push(action.payload);
        state.status = 'succeeded';
      })
      // updateTask
      .addCase(updateTask.fulfilled, (state, action) => {
        const index = state.tasks.findIndex((task) => task.id === action.payload.id);
        if (index !== -1) {
          state.tasks[index] = action.payload; // Replace updated task
        }
        state.status = 'succeeded';
      })
      // deleteTask
      .addCase(deleteTask.fulfilled, (state, action) => {
        state.tasks = state.tasks.filter((task) => task.id !== action.payload);
        state.status = 'succeeded';
      })
      // runSimulation
      .addCase(runSimulation.pending, (state) => {
        state.status = 'loading';
        state.simulationResult = null; // Clear previous results
      })
      .addCase(runSimulation.fulfilled, (state) => {
        // Now only indicates that the simulation has started in the background
        state.status = 'loading'; // Stay in loading state until results are fetched
      })
      .addCase(runSimulation.rejected, (state, action) => {
        state.status = 'failed';
        state.error = action.error.message || 'Failed to start simulation';
      })
      // fetchSimulationResult
      .addCase(fetchSimulationResult.pending, (state) => {
        state.status = 'loading';
      })
      .addCase(fetchSimulationResult.fulfilled, (state, action) => {
        state.simulationResult = action.payload;
        state.status = 'succeeded';
      })
      .addCase(fetchSimulationResult.rejected, (state, action) => {
        state.status = 'failed';
        state.error = action.error.message || 'Failed to fetch simulation result';
      })
      // createRisk
      .addCase(createRisk.fulfilled, (state, action) => {
        state.risks.push(action.payload);
        state.status = 'succeeded';
      })
      // updateRisk
      .addCase(updateRisk.fulfilled, (state, action) => {
        const index = state.risks.findIndex((risk) => risk.id === action.payload.id);
        if (index !== -1) {
          state.risks[index] = action.payload;
        }
        state.status = 'succeeded';
      })
      // deleteRisk
      .addCase(deleteRisk.fulfilled, (state, action) => {
        state.risks = state.risks.filter((risk) => risk.id !== action.payload);
        state.status = 'succeeded';
      });
  },
});

export const { setCurrentProject, addTask, updateTaskParent, updateTaskField } = projectSlice.actions;

export default projectSlice.reducer;

export interface Project {
  id: number;
  name: string;
  description: string;
  budget: number;
  contingency: number; // Percentage
  start_date: string;
  end_date: string;
}

export interface Task {
  id: number;
  text: string;
  start_date: string;
  duration: number;
  progress: number;
  parent: number | null;
  dependencies: number[]; // Array of task IDs that must be completed before this task can start
  cost: number;
  resource_id?: number;
  project_id: number;
}

export interface Resource {
  id: number; // Assuming resource IDs are numbers
  name: string;
  cost_per_day: number;
}

export type RiskLikelihood = 'Low' | 'Medium' | 'High';
export type RiskImpact = 'Low' | 'Medium' | 'High';

export interface Risk {
  id: number; // Assuming risk IDs are numbers
  description: string;
  likelihood: RiskLikelihood;
  impact: RiskImpact;
  // Probability is derived from likelihood, e.g., Low=0.1, Medium=0.3, High=0.6
  probability: number; 
  // Cost impact is derived from impact level, e.g., Low=5000, Medium=20000, High=50000
  cost_impact: number;
  // Duration impact in days
  duration_impact: number; 
  affected_task_ids: number[]; // Now numbers
}

export interface SimulationRun {
  id: number;
  project_id: number;
  status: string;
  created_at: string;
  started_at?: string | null;
  completed_at?: string | null;
  total_duration?: number | null;
  total_cost?: number | null;
  critical_path?: number[];
  results?: SimulationResults | null;
}

export interface SimulationResults {
  total_duration?: number;
  total_cost?: number;
  tasks_completed?: number;
  risk_events?: number;
  event_count?: number;
  base_duration?: number;
  critical_path?: number[];
  timeline?: { day: number; active: number; completed: number }[];
  p80_cost?: number; // optional future fields
  p80_duration?: number;
  base_cost?: number;
  mean_duration?: number;
  std_dev_duration?: number;
  p50_duration?: number;
  p90_duration?: number;
  mean_cost?: number;
  std_dev_cost?: number;
  p50_cost?: number;
  p90_cost?: number;
  iterations?: number;
  duration_distribution?: number[];
  bin_edges_duration?: number[];
  cost_distribution?: number[];
  bin_edges_cost?: number[];
  ai_assessment?: string;
  ai_recommendations?: string[];
  finalCost?: number;
  finalDuration?: number;
  risksOccurred?: number;
}

// Data structure for the Gantt chart
export interface GanttTask {
    id: number;
    start_date: string;
    text: string;
    duration: number;
    progress: number;
    parent?: number | null; // Now number or null
    cost?: number;
    // DHTMLX Gantt specific fields
    type?: string; 
    open?: boolean;
}

export interface GanttLink {
    id: number;
    source: number;
    target: number;
    type: string; // e.g., '0' for finish_to_start
}

// For simulation logs
export type SimulationEventType =
  | 'TASK_START'
  | 'TASK_END'
  | 'RISK_EVENT'
  | 'SIM_START'
  | 'SIM_END'
  | 'task_started'
  | 'task_completed'
  | 'simulation_completed'
  | 'connected'
  | 'pong';

export interface SimulationEvent {
    timestamp: string | number;
    type?: SimulationEventType | string;
    event_type?: SimulationEventType | string;
    message?: string;
    task_id?: number;
    risk_id?: number;
    details?: Record<string, unknown>;
}

// For KPIs
export interface KpiValues {
    pv: number; // Planned Value
    ev: number; // Earned Value
    ac: number; // Actual Cost
    sv: number; // Schedule Variance (EV - PV)
    cv: number; // Cost Variance (EV - AC)
    rei: number; // Risk Exposure Index
}

