  console.log(`API: Deleting risk ${riskId}...`);
  const response = await fetch(`${API_BASE_URL}/risks/${riskId}`, {
    method: 'DELETE',
  });
  if (!response.ok) {
    throw new Error('Failed to delete risk');
  }
};

